/*
  # Real HR document suite for Nikki Technologies

  Expands from 6 document types to a full professional set covering the entire
  employment lifecycle: hiring → confirmation → policies → recognition →
  discipline → exit.

  ⚠ IMPORTANT — READ BEFORE USING IN PRODUCTION
  These are professionally written, India-context templates, but they are NOT
  legal advice and have NOT been reviewed by a lawyer. Before issuing any of
  these to a real employee, have a labour-law advocate review at minimum:
    - Appointment Letter (it is an employment contract)
    - NDA / Confidentiality Agreement (enforceability varies)
    - POSH Policy (governed by the Sexual Harassment of Women at Workplace
      (Prevention, Prohibition and Redressal) Act, 2013 — mandatory for any
      workplace with 10+ employees, and it legally requires you to constitute
      an Internal Committee (IC) and name real members. The template below
      leaves those as placeholders you MUST fill in.)
    - Notice period, probation and termination clauses (state-specific rules)

  Every template is editable in Super Admin → Documents & Onboarding, so you can
  adjust wording after legal review without touching code.
*/

-- ═══════════════════════════════════════════════════════════════
-- 1. Expand allowed document types
-- ═══════════════════════════════════════════════════════════════
ALTER TABLE document_templates DROP CONSTRAINT IF EXISTS document_templates_doc_type_check;
ALTER TABLE document_templates ADD CONSTRAINT document_templates_doc_type_check
  CHECK (doc_type IN (
    'offer_letter','appointment_letter','welcome_letter','roles_responsibilities',
    'job_description','confirmation_letter','nda','code_of_conduct','posh_policy',
    'it_asset_policy','leave_policy','salary_certificate','increment_letter',
    'warning_letter','experience_letter','relieving_letter','internship_certificate',
    'policy','other'
  ));

ALTER TABLE employee_documents DROP CONSTRAINT IF EXISTS employee_documents_doc_type_check;
ALTER TABLE employee_documents ADD CONSTRAINT employee_documents_doc_type_check
  CHECK (doc_type IN (
    'offer_letter','appointment_letter','welcome_letter','roles_responsibilities',
    'job_description','confirmation_letter','nda','code_of_conduct','posh_policy',
    'it_asset_policy','leave_policy','salary_certificate','increment_letter',
    'warning_letter','experience_letter','relieving_letter','internship_certificate',
    'policy','other'
  ));

-- ═══════════════════════════════════════════════════════════════
-- 2. Appointment Letter (the actual employment contract)
-- ═══════════════════════════════════════════════════════════════
INSERT INTO document_templates (segment_slug, doc_type, title, body, requires_signature) VALUES
(NULL, 'appointment_letter', 'Appointment Letter', E'NIKKI TECHNOLOGIES\nHyderabad, Telangana, India\n\nDate: {{today}}\n\nTo,\n{{name}}\n\nSubject: Letter of Appointment\n\nDear {{name}},\n\nFurther to your acceptance of our offer, we are pleased to confirm your appointment with Nikki Technologies on the following terms and conditions.\n\n1. POSITION\nYou are appointed as {{designation}} in our {{segment}} division. You will report to your Segment Manager or such other person as the Company may designate.\n\n2. DATE OF JOINING\nYour employment commences on {{joining_date}}.\n\n3. EMPLOYMENT TYPE\n{{employment_type}}\n\n4. PLACE OF WORK\nYour place of work will be Hyderabad. The Company may, at its discretion and with reasonable notice, require you to work from another location or from home as business needs require.\n\n5. WORKING HOURS\n{{reporting_time}}\n\n6. REMUNERATION\nYour total annual cost to company (CTC) is Rs. {{ctc}}. A detailed salary breakdown is available in your staff portal. Salary is payable monthly, subject to statutory deductions including TDS as applicable.\n\n7. PROBATION\nYou will be on probation for a period of three (3) months from your date of joining. During probation, either party may terminate this employment with seven (7) days written notice. Your confirmation is subject to satisfactory performance and will be communicated in writing.\n\n8. NOTICE PERIOD\nAfter confirmation, either party may terminate this employment by giving thirty (30) days written notice or salary in lieu thereof.\n\n9. CONFIDENTIALITY\nYou will have access to confidential information belonging to the Company and its clients. You agree not to disclose such information during or after your employment. This is further governed by the Confidentiality Agreement issued separately.\n\n10. COMPANY POLICIES\nYou agree to abide by all Company policies, including the Code of Conduct, IT and Asset Policy, Leave Policy, and the Policy on Prevention of Sexual Harassment, each of which is provided to you separately and may be updated from time to time.\n\n11. GENERAL\nThis appointment is subject to verification of the documents and information provided by you. Any misrepresentation may result in termination.\n\nPlease sign this letter in your staff portal to confirm your acceptance of these terms.\n\nWe look forward to a long and rewarding association.\n\nFor Nikki Technologies\n\n_______________________\nAuthorised Signatory', true),

-- ═══════════════════════════════════════════════════════════════
-- 3. Confirmation Letter (end of probation)
-- ═══════════════════════════════════════════════════════════════
(NULL, 'confirmation_letter', 'Confirmation of Employment', E'NIKKI TECHNOLOGIES\n\nDate: {{today}}\n\nTo,\n{{name}}\n{{designation}} — {{segment}}\n\nSubject: Confirmation of Employment\n\nDear {{name}},\n\nWe are pleased to inform you that, based on your performance during the probationary period, your services with Nikki Technologies stand confirmed with effect from {{today}}.\n\nYour designation remains {{designation}} in the {{segment}} division.\n\nAll other terms and conditions of your appointment letter dated on or around {{joining_date}} remain unchanged, save that your notice period is now thirty (30) days as per the terms of your appointment.\n\nWe appreciate the contribution you have made so far and look forward to your continued growth with us.\n\nFor Nikki Technologies\n\n_______________________\nAuthorised Signatory', false),

-- ═══════════════════════════════════════════════════════════════
-- 4. NDA / Confidentiality Agreement
-- ═══════════════════════════════════════════════════════════════
(NULL, 'nda', 'Confidentiality & Non-Disclosure Agreement', E'NIKKI TECHNOLOGIES\nCONFIDENTIALITY AND NON-DISCLOSURE AGREEMENT\n\nThis Agreement is entered into on {{today}} between Nikki Technologies ("the Company") and {{name}}, {{designation}} ("the Employee").\n\n1. CONFIDENTIAL INFORMATION\nIn the course of your employment you will have access to information that is confidential to the Company and to its clients, including but not limited to:\n  a) Client lists, contact details, contracts, pricing and commercial terms\n  b) Campaign data, analytics, advertising account access and performance figures\n  c) Source code, technical architecture, databases, credentials and API keys\n  d) Product roadmaps, designs and unreleased features\n  e) Employee records, salary information and internal financial data\n  f) Any information marked confidential or which a reasonable person would understand to be confidential\n\n2. OBLIGATIONS\nYou agree that you will:\n  a) Keep all Confidential Information strictly confidential\n  b) Use it solely for the purpose of performing your duties\n  c) Not copy, transmit, publish or share it with any third party without written authorisation\n  d) Not use it for personal gain or for the benefit of any other business\n  e) Take reasonable care to prevent unauthorised access, including protecting devices and passwords\n\n3. CLIENT DATA\nYou acknowledge that client data handled by the Company may include personal information of third parties. You agree to handle such data only as instructed and never to retain personal copies.\n\n4. RETURN OF MATERIALS\nOn cessation of employment, or earlier if requested, you will return all Company and client property, delete Company data from personal devices, and surrender all access credentials.\n\n5. DURATION\nThese obligations apply during your employment and continue for a period of three (3) years after it ends. Obligations relating to trade secrets and client personal data continue indefinitely.\n\n6. BREACH\nBreach of this Agreement may result in disciplinary action including termination, and the Company reserves the right to pursue legal remedies for any loss suffered.\n\nBy signing below, you confirm you have read, understood and agree to be bound by this Agreement.\n\nEmployee: {{name}}\nEmployee ID: {{staff_code}}\nDate: {{today}}', true),

-- ═══════════════════════════════════════════════════════════════
-- 5. Code of Conduct
-- ═══════════════════════════════════════════════════════════════
(NULL, 'code_of_conduct', 'Code of Conduct', E'NIKKI TECHNOLOGIES\nCODE OF CONDUCT\n\nIssued to: {{name}} ({{designation}}, {{segment}})\n\nThis Code sets out the standards of behaviour expected of everyone at Nikki Technologies. It applies at our offices, at client sites, during travel, and on any Company communication channel.\n\n1. PROFESSIONAL CONDUCT\n  - Treat colleagues, clients and vendors with courtesy and respect at all times\n  - Be punctual and reliable; inform your manager in advance if you cannot attend\n  - Represent the Company professionally in dress, language and behaviour when meeting clients\n  - Do not consume alcohol or any intoxicating substance during working hours or at client premises\n\n2. HONESTY AND INTEGRITY\n  - Record attendance, expenses, leads and work reports truthfully\n  - Do not falsify records, inflate figures, or misreport work performed\n  - Declare any conflict of interest, including outside employment or a personal interest in a client or vendor\n  - Do not accept gifts, commissions or favours from clients or vendors beyond nominal courtesy\n\n3. RESPECT AND NON-DISCRIMINATION\n  - Discrimination or harassment on the basis of gender, religion, caste, region, language, disability, age or any other ground is strictly prohibited\n  - Bullying, intimidation, offensive language and inappropriate physical contact are prohibited\n  - Sexual harassment is separately and specifically prohibited under our POSH Policy\n\n4. CLIENT RELATIONSHIPS\n  - Never make commitments on behalf of the Company that you are not authorised to make\n  - Do not approach or solicit Company clients for personal business\n  - Escalate client complaints promptly rather than concealing them\n\n5. COMPANY PROPERTY AND DATA\n  - Use Company devices, accounts and data only for legitimate work purposes\n  - Do not share login credentials\n  - Report loss, theft or any suspected data breach immediately\n\n6. SOCIAL MEDIA AND PUBLIC COMMENT\n  - Do not disclose Company or client information on personal social media\n  - Do not speak to media on behalf of the Company without authorisation\n\n7. REPORTING CONCERNS\nIf you witness a breach of this Code, report it to your manager, to HR, or directly to the Management. Reports made in good faith will be treated confidentially and no retaliation will be permitted against anyone who raises a genuine concern.\n\n8. CONSEQUENCES\nBreach of this Code may result in disciplinary action up to and including termination of employment, and where applicable, legal action.\n\nI confirm I have read and understood this Code of Conduct.\n\nEmployee: {{name}}\nDate: {{today}}', true),

-- ═══════════════════════════════════════════════════════════════
-- 6. POSH Policy (legally mandated in India for 10+ employees)
-- ═══════════════════════════════════════════════════════════════
(NULL, 'posh_policy', 'Policy on Prevention of Sexual Harassment (POSH)', E'NIKKI TECHNOLOGIES\nPOLICY ON PREVENTION OF SEXUAL HARASSMENT AT THE WORKPLACE\n\nIssued in accordance with the Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013 and the Rules made thereunder.\n\n⚠ ACTION REQUIRED BY MANAGEMENT: The Internal Committee members named in Section 5 MUST be filled in with real names and contact details before this policy is issued. The Act requires an Internal Committee with a woman Presiding Officer, at least two employee members, and one external member from an NGO or a person familiar with issues relating to sexual harassment.\n\n1. COMMITMENT\nNikki Technologies is committed to providing a workplace free from sexual harassment. Every employee has the right to be treated with dignity. Sexual harassment will not be tolerated in any form and will result in strict disciplinary action.\n\n2. SCOPE\nThis policy applies to all employees regardless of role or seniority, and to interns, trainees, contractors and visitors. It applies at our premises, at client sites, at any location visited during the course of work, during work travel, at work-related events, and on digital communication channels used for work.\n\n3. WHAT CONSTITUTES SEXUAL HARASSMENT\nSexual harassment includes any one or more of the following unwelcome acts or behaviour, whether directly or by implication:\n  a) Physical contact and advances\n  b) A demand or request for sexual favours\n  c) Making sexually coloured remarks\n  d) Showing pornography\n  e) Any other unwelcome physical, verbal or non-verbal conduct of a sexual nature\n\nThe following circumstances, if they occur in relation to any act of sexual harassment, may also amount to sexual harassment:\n  - Implied or explicit promise of preferential treatment in employment\n  - Implied or explicit threat of detrimental treatment in employment\n  - Implied or explicit threat about present or future employment status\n  - Interference with work, or creating an intimidating, offensive or hostile work environment\n  - Humiliating treatment likely to affect health or safety\n\n4. YOUR RIGHT TO COMPLAIN\nAny woman who believes she has been subjected to sexual harassment at the workplace may make a written complaint to the Internal Committee within three (3) months of the incident, or within three months of the last incident in a series. The Committee may extend this period if satisfied that circumstances prevented timely filing.\n\nIf you are unable to make the complaint in writing, the Committee will provide reasonable assistance to help you do so.\n\n5. INTERNAL COMMITTEE (IC)\n\n  Presiding Officer (woman, senior level):\n    Name: ______________________  Contact: ______________________\n\n  Member (employee):\n    Name: ______________________  Contact: ______________________\n\n  Member (employee):\n    Name: ______________________  Contact: ______________________\n\n  External Member (from an NGO or person familiar with POSH issues):\n    Name: ______________________  Contact: ______________________\n\n6. PROCESS\n  a) On receiving a complaint, the IC will provide a copy to the respondent within seven working days\n  b) The respondent must reply with supporting documents within ten working days\n  c) The IC will complete its inquiry within ninety (90) days\n  d) The IC will submit its report within ten days of completing the inquiry\n  e) Action recommended by the IC will be implemented within sixty (60) days\n\n7. CONCILIATION\nBefore initiating an inquiry, the IC may, at the request of the complainant, attempt to settle the matter through conciliation. No monetary settlement shall be the basis of conciliation. Conciliation will not be attempted at the Company\'s initiative.\n\n8. CONFIDENTIALITY\nThe identity of the complainant, respondent, witnesses, the contents of the complaint and the inquiry proceedings shall not be published or made public in any manner.\n\n9. PROTECTION AGAINST RETALIATION\nNo person who makes a complaint in good faith, or who assists in an inquiry, shall be subjected to any retaliation, victimisation or adverse treatment. Retaliation is itself a serious disciplinary offence.\n\n10. ACTION ON COMPLAINTS FOUND VALID\nWhere the allegation is proved, the IC may recommend action including written apology, warning, withholding of promotion or increment, suspension, termination of employment, and deduction from salary as compensation to the aggrieved woman.\n\n11. MALICIOUS COMPLAINTS\nWhere a complaint is found to be malicious or made knowing it to be false, action may be taken against the complainant. However, mere inability to substantiate a complaint made in good faith shall NOT attract any action.\n\n12. AWARENESS\nThis policy is provided to every employee on joining, is displayed at the workplace, and forms part of induction. Any queries may be raised with HR or with any member of the Internal Committee.\n\nI confirm I have received, read and understood this Policy.\n\nEmployee: {{name}}\nEmployee ID: {{staff_code}}\nDate: {{today}}', true),

-- ═══════════════════════════════════════════════════════════════
-- 7. IT & Asset Policy
-- ═══════════════════════════════════════════════════════════════
(NULL, 'it_asset_policy', 'IT & Asset Usage Policy', E'NIKKI TECHNOLOGIES\nIT AND ASSET USAGE POLICY\n\nIssued to: {{name}} ({{designation}}, {{segment}})\n\n1. COMPANY ASSETS\nAny laptop, phone, SIM, camera, storage device, vehicle or other asset issued to you remains the property of Nikki Technologies. You are responsible for its safe custody and reasonable care. Loss or damage due to negligence may be recoverable.\n\n2. ACCEPTABLE USE\n  - Company devices and accounts are provided for business use\n  - Limited personal use is permitted provided it does not interfere with work, incur cost, or breach this policy\n  - Do not install unlicensed or pirated software\n  - Do not use Company systems to access, store or transmit unlawful, obscene or offensive material\n\n3. ACCOUNTS AND CREDENTIALS\n  - Never share your login credentials with anyone, including colleagues\n  - Use strong, unique passwords and enable two-factor authentication where available\n  - Client advertising accounts, hosting panels, databases and admin dashboards must only be accessed by authorised personnel\n  - Do not store client credentials in personal notes, personal cloud drives or messaging apps\n\n4. DATA HANDLING\n  - Client data and Company data must be stored only in approved Company systems\n  - Do not copy client databases, lead lists or campaign data to personal devices or personal accounts\n  - Do not photograph screens containing client or employee personal data\n  - Report any suspected data breach or lost device to Management IMMEDIATELY — early reporting limits damage and will not itself be treated as misconduct\n\n5. CODE AND INTELLECTUAL PROPERTY\n  - All code, designs, creatives, documents and materials produced in the course of your employment are the property of Nikki Technologies\n  - Do not publish Company or client code to public repositories\n  - Do not reuse client work for other clients or for personal portfolio without written permission\n\n6. COMMUNICATION\n  - Use Company-approved channels for work communication so records are retained\n  - Do not conduct Company business exclusively through personal accounts\n\n7. ON EXIT\nOn your last working day you must return all Company assets in working condition, hand over all credentials, and remove Company and client data from any personal device.\n\n8. MONITORING\nThe Company may monitor use of its systems and accounts for security and compliance purposes, in accordance with applicable law.\n\nBreach of this policy may result in disciplinary action and recovery of any loss caused.\n\nEmployee: {{name}}\nDate: {{today}}', true),

-- ═══════════════════════════════════════════════════════════════
-- 8. Leave Policy
-- ═══════════════════════════════════════════════════════════════
(NULL, 'leave_policy', 'Leave Policy', E'NIKKI TECHNOLOGIES\nLEAVE POLICY\n\nIssued to: {{name}} ({{designation}}, {{segment}})\n\n1. LEAVE YEAR\nThe leave year runs from 1 January to 31 December.\n\n2. TYPES OF LEAVE\n  a) Casual Leave — for short, unplanned personal needs\n  b) Sick Leave — for illness. A medical certificate may be required for absences exceeding two consecutive days\n  c) Earned Leave — accrued and available for planned time off\n  d) Unpaid Leave — where paid balances are exhausted or the leave type does not apply\n\nYour exact entitlement for each type is shown in your staff portal under Leaves & Advances, and is set by HR according to your role and employment type.\n\n3. APPLYING FOR LEAVE\n  - Apply through the staff portal, not by message or verbally\n  - Planned leave should be applied for at least three (3) working days in advance; longer leave should be applied for further in advance\n  - Leave is not confirmed until approved by your manager or HR\n  - In an emergency, inform your manager as early as possible and record the leave in the portal on your return\n\n4. HALF-DAY LEAVE\nHalf-day leave may be applied for the first or second half of the working day, subject to approval.\n\n5. PUBLIC HOLIDAYS\nThe Company observes a published list of holidays each year, available in your staff portal. Holidays are not deducted from your leave balance.\n\n6. UNAPPROVED ABSENCE\nAbsence without approved leave and without informing your manager may be treated as unpaid absence and, if repeated, as a disciplinary matter.\n\n7. LEAVE DURING NOTICE PERIOD\nLeave during the notice period is at the discretion of Management and is generally not approved except in genuine emergencies.\n\n8. ATTENDANCE CORRECTIONS\nIf you were present but were unable to check in or out (for example, a device or network issue on site), raise an Attendance Correction request in the portal with the actual times and reason. Do not apply for leave for a day you actually worked.\n\nEmployee: {{name}}\nDate: {{today}}', false),

-- ═══════════════════════════════════════════════════════════════
